  onToggleBirthday: (id: string) => void;
}

const AttendanceRow: React.FC<Props> = ({ 
  member, 
  isAttending, 
  isBirthday, 
  onToggleAttendance, 
  onToggleBirthday 
}) => {
  return (
    <div className={`flex items-center justify-between p-3 rounded-lg border transition-all ${isAttending ? 'bg-white border-gray-200' : 'bg-gray-100 border-gray-300 opacity-70'}`}>
      <div className="flex items-center gap-3">
        <div className={`w-8 h-8 flex items-center justify-center rounded-full text-sm font-bold ${isAttending ? 'bg-blue-100 text-blue-600' : 'bg-gray-200 text-gray-500'}`}>
          {member.name.charAt(0)}
        </div>
        <span className={`font-medium ${isAttending ? 'text-gray-900' : 'text-gray-500'}`}>{member.name}</span>
      </div>

      <div className="flex items-center gap-4">
        <label className="flex items-center gap-2 cursor-pointer group">
          <input 
            type="checkbox" 
            checked={isAttending}
            onChange={() => onToggleAttendance(member.id)}
            className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 transition-all"
          />
          <span className="text-sm text-gray-600 group-hover:text-blue-600">出席</span>
        </label>

