            onChange={() => onToggleBirthday(member.id)}
            className="w-5 h-5 rounded border-gray-300 text-pink-500 focus:ring-pink-500 transition-all"
          />
          <span className="text-sm text-gray-600 group-hover:text-pink-500">壽星</span>
        </label>
      </div>
    </div>
  );
};

