              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <XAxis dataKey="name" fontSize={10} axisLine={false} tickLine={false} />
                    <YAxis fontSize={10} axisLine={false} tickLine={false} />
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                    />
                    <Legend iconType="circle" />
                    <Bar dataKey="budget" name="預算" fill="#3B82F6" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="expense" name="支出" fill="#F43F5E" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
              <h3 className="text-lg font-bold text-gray-800 mb-4">缺席次數分佈</h3>
              <div className="overflow-y-auto max-h-64 pr-2 space-y-2">
                {MEMBERS.map(m => {
                  const count = yearEndSummary.attendanceStats[m.id];
                  const isEligible = count <= MAX_ABSENCES_FOR_BONUS;
                  return (
                    <div key={m.id} className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full ${isEligible ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                        <span className="text-gray-700 font-medium">{m.name}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-gray-500">{count} 次缺席</span>
                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${isEligible ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                          {isEligible ? '合資格' : '不合資格'}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          </div>
        </div>
      </div>

      <footer className="text-center py-8 text-gray-400 text-sm border-t border-gray-100">
        &copy; {new Date().getFullYear()} 餐費獎金庫管理系統. 助您輕鬆管理團隊聚餐財務。
      </footer>
    </div>
  );
};

