import React, { useEffect, useState } from 'react';
import { Member } from '../types';

interface Props {
  member: Member;
  isAttending: boolean;
  isBirthday: boolean;
  onToggleAttendance: (id: string) => void;
  onToggleBirthday: (id: string) => void;
}

const AttendanceRow: React.FC<Props> = ({ 
  member, 
  isAttending, 
  isBirthday, 
  onToggleAttendance, 
  onToggleBirthday 
}) => {
  const [isAnimating, setIsAnimating] = useState(false);

  // Trigger animation when attendance status changes
  useEffect(() => {
    setIsAnimating(true);
    const timer = setTimeout(() => setIsAnimating(false), 250);
    return () => clearTimeout(timer);
  }, [isAttending]);

  return (
    <div className={`flex items-center justify-between p-3 border-4 transition-all duration-300 ${
      isAttending 
