        <div className="p-4 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {MEMBERS.map(m => (
            <AttendanceRow 
              key={m.id}
              member={m}
              isAttending={activeRecord.attendeeIds.includes(m.id)}
              isBirthday={m.birthdayMonth === activeMonth + 1}
